import{_ as E,C as o,o as r,c as h,a2 as d,b as s,w as a,a as l,E as A,a3 as B}from"./chunks/framework.CFuv5BrO.js";const D=JSON.parse('{"title":"Hearth OS · 任务执行调度器设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/Hearth-任务执行调度器设计说明.md","filePath":"architecture/Hearth-任务执行调度器设计说明.md","lastUpdated":null}'),i={name:"architecture/Hearth-任务执行调度器设计说明.md"};function n(c,t,p,_,b,u){const e=o("Mermaid");return r(),h("div",null,[t[1]||(t[1]=d('<h1 id="hearth-os-·-任务执行调度器设计说明" tabindex="-1">Hearth OS · 任务执行调度器设计说明 <a class="header-anchor" href="#hearth-os-·-任务执行调度器设计说明" aria-label="Permalink to &quot;Hearth OS · 任务执行调度器设计说明&quot;">​</a></h1><blockquote><p>本文只依据项目源码整理（<code>apps/server/src</code> 下调度、租约、失败策略、完成判定、任务图与进度相关文件），未参考 <code>docs/</code> 与 <code>README.md</code>；文中不列举任何具体代码，括号内的文件名仅用于定位核对。 整理日期：2026-11-13</p></blockquote><p><strong>本文边界（避免与本套其它说明重复）</strong></p><table tabindex="0"><thead><tr><th>已讲过的内容</th><th>在哪份文档</th><th>本文的处理</th></tr></thead><tbody><tr><td>定时计划何时触发、补跑与冷却</td><td><a href="./定时任务设计说明.html">定时任务设计说明</a></td><td>该文档已明确「执行调度器不是主角」，本文补足它，但不重复定时计划</td></tr><tr><td>审批票与等待状态如何落地</td><td><a href="./判定审批机制说明.html">判定审批机制说明</a></td><td>只讲调度器在挂起期间做什么</td></tr><tr><td>上下文如何编译、失败如何交接</td><td><a href="./hearth-os-上下文管理设计.html">hearth-os-上下文管理设计</a></td><td>只讲调度器消费这些结论的动作，不重讲接管链路</td></tr><tr><td>事件如何落库</td><td><a href="./Hearth-存储设计说明.html">Hearth-存储设计说明</a></td><td>不展开</td></tr><tr><td>执行器如何接模型、怎么起进程</td><td><a href="./Hearth-模型接入与执行器适配设计说明.html">Hearth-模型接入与执行器适配设计说明</a></td><td>不展开</td></tr></tbody></table><p>本文只讲：<strong>一个已创建的任务，是怎么被挑出来、跑起来、挂起、重试、判定完成并回收产物的</strong>。</p><hr><h2 id="_0-一句话总览" tabindex="-1">0. 一句话总览 <a class="header-anchor" href="#_0-一句话总览" aria-label="Permalink to &quot;0. 一句话总览&quot;">​</a></h2><p>它是一个<strong>事件唤醒的单进程常驻编排循环</strong>：自己不跑模型，只负责在并发配额与租约约束下挑任务、把任务交给执行器、接住各种中断、再决定下一步。真正干活的是执行器适配层与 Agent 运行时。</p><hr><h2 id="_1-先定性-三个容易误解的地方" tabindex="-1">1. 先定性：三个容易误解的地方 <a class="header-anchor" href="#_1-先定性-三个容易误解的地方" aria-label="Permalink to &quot;1. 先定性：三个容易误解的地方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>代码里的实际做法</th></tr></thead><tbody><tr><td>以为有个定时轮询不断扫队列</td><td>主循环在无事可做时挂起在一个 Promise 上，靠事件唤醒，没有固定轮询间隔</td></tr><tr><td>以为「可以继续」是中间状态</td><td>它被判定为<strong>终态</strong>：调度器不会自动把它拉起来，必须人工重试、补充指令或跟进消息唤醒</td></tr><tr><td>以为租约只是个锁</td><td>它带递增的代次（epoch），旧代次提交的结果会被直接拒绝，是防「脑裂双写」的栅栏</td></tr></tbody></table><hr><h2 id="_2-主循环与唤醒源" tabindex="-1">2. 主循环与唤醒源 <a class="header-anchor" href="#_2-主循环与唤醒源" aria-label="Permalink to &quot;2. 主循环与唤醒源&quot;">​</a></h2><p>启动时先订阅存储层事件，然后进入循环：反复尝试「把可跑的任务安排上」，一次都没安排成就挂起等待唤醒。唤醒是一个可解析的 Promise，任何一处调用唤醒都会让它继续下一轮，因此不存在空转轮询。</p><p>唤醒来源包括：任务创建或更新、跟进消息、显式重试、交接确认、追加预算、审批完成、取消与停止、委派与交接确认。终态事件还会触发在途资源的清理。</p><p>停止时设置标志并主动解除挂起，让循环自然收敛，而不是硬杀进程。</p><hr><h2 id="_3-并发与配额" tabindex="-1">3. 并发与配额 <a class="header-anchor" href="#_3-并发与配额" aria-label="Permalink to &quot;3. 并发与配额&quot;">​</a></h2><p>任务按执行器分组，每组有独立的并发上限：</p><table tabindex="0"><thead><tr><th>项</th><th>默认值 / 规则</th></tr></thead><tbody><tr><td>每执行器默认并发</td><td>3，允许配置 1–4，非整数会四舍五入后钳制</td></tr><tr><td>配置缺该执行器键时</td><td>按 <strong>1</strong> 处理，而不是按默认 3</td></tr><tr><td>子任务并行</td><td>另受任务图的并行上限约束，默认 3</td></tr></tbody></table><p>「缺键按 1」是一个很容易读错的地方：默认 3 只写在配置归一化函数里，实际取并发时用的是空值回退到 1。因此新增执行器若忘记写配置，会悄悄变成串行。</p><hr><h2 id="_4-租约-代次栅栏与心跳" tabindex="-1">4. 租约：代次栅栏与心跳 <a class="header-anchor" href="#_4-租约-代次栅栏与心跳" aria-label="Permalink to &quot;4. 租约：代次栅栏与心跳&quot;">​</a></h2><p>每个运行中的任务会拿到一条租约，记录持有实例、代次、过期时间。代次在每次获取时自增。</p><table tabindex="0"><thead><tr><th>项</th><th>值 / 行为</th></tr></thead><tbody><tr><td>有效期</td><td>60 秒，可配置但不得低于 1 秒</td></tr><tr><td>心跳</td><td>每 15 秒续期一次</td></tr><tr><td>他人持有</td><td>拒绝获取</td></tr><tr><td>租约过期</td><td>拒绝再提交结果</td></tr><tr><td>代次或持有者不匹配</td><td>旧结果被拒（栅栏）</td></tr></tbody></table><p>心跳失败会直接中止当前运行的取消信号，并丢弃在途结果——宁可重跑，也不接受一个可能已经被别的实例接管的写入。</p><p><strong>一个刻意的不对称</strong>：任务进入「等你确认」而挂起时，收尾逻辑<strong>不释放租约</strong>；其它所有路径都会释放。这样审批回来后仍能用同一代次续跑，不会被另一个实例抢走。</p><hr><h2 id="_5-一次运行的生命周期" tabindex="-1">5. 一次运行的生命周期 <a class="header-anchor" href="#_5-一次运行的生命周期" aria-label="Permalink to &quot;5. 一次运行的生命周期&quot;">​</a></h2>',29)),(r(),s(B,null,{default:a(()=>[A(e,{id:"mermaid-267",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E4%BB%BB%E5%8A%A1%E8%BF%9B%E5%85%A5%E9%98%9F%E5%88%97%5D%20--%3E%20B%5B%E5%94%A4%E9%86%92%E5%BE%AA%E7%8E%AF%20%C2%B7%20%E6%A3%80%E6%9F%A5%E5%B9%B6%E5%8F%91%E4%B8%8E%E7%A7%9F%E7%BA%A6%5D%0A%20%20%20%20B%20--%3E%20C%5B%E5%88%9B%E5%BB%BA%E8%BF%90%E8%A1%8C%E8%AE%B0%E5%BD%95%20%C2%B7%20%E5%87%86%E5%A4%87%E5%B7%A5%E4%BD%9C%E5%8C%BA%E4%B8%8E%E6%9D%83%E9%99%90%5D%0A%20%20%20%20C%20--%3E%20D%5B%E4%BA%A4%E7%BB%99%E6%89%A7%E8%A1%8C%E5%99%A8%E9%80%82%E9%85%8D%E5%B1%82%5D%0A%20%20%20%20D%20--%3E%20E%7B%E8%BF%90%E8%A1%8C%E4%B8%AD%E9%81%87%E5%88%B0%E4%BB%80%E4%B9%88%7D%0A%20%20%20%20E%20--%3E%7C%E7%BC%BA%E4%BF%A1%E6%81%AF%7C%20F%5B%E7%AD%89%E5%BE%85%E8%A1%A5%E5%85%85%20%C2%B7%20%E6%94%B6%E5%B0%BE%5D%0A%20%20%20%20E%20--%3E%7C%E9%A2%84%E7%AE%97%E8%A7%A6%E9%A1%B6%7C%20G%5B%E7%AD%89%E5%BE%85%E9%A2%84%E7%AE%97%20%C2%B7%20%E5%8F%AF%E8%BF%BD%E5%8A%A0%5D%0A%20%20%20%20E%20--%3E%7C%E6%95%8F%E6%84%9F%E5%B7%A5%E5%85%B7%7C%20H%5B%E7%AD%89%E5%BE%85%E5%AE%A1%E6%89%B9%20%C2%B7%20%E4%BF%9D%E7%95%99%E7%A7%9F%E7%BA%A6%5D%0A%20%20%20%20E%20--%3E%7C%E6%AD%A3%E5%B8%B8%E7%BB%93%E6%9D%9F%7C%20I%5B%E5%AE%8C%E6%88%90%E5%88%A4%E5%AE%9A%5D%0A%20%20%20%20E%20--%3E%7C%E6%8A%A5%E9%94%99%7C%20J%5B%E5%A4%B1%E8%B4%A5%E5%88%86%E7%B1%BB%E4%B8%8E%E5%A4%84%E7%BD%AE%5D%0A%20%20%20%20J%20--%3E%20K%7B%E5%A4%84%E7%BD%AE%E7%BB%93%E6%9E%9C%7D%0A%20%20%20%20K%20--%3E%7C%E7%9B%B2%E9%87%8D%E8%AF%95%20%2F%20%E4%BF%AE%E5%A4%8D%20%2F%20%E5%AF%B9%E8%B4%A6%20%2F%20%E6%8D%A2%E6%89%A7%E8%A1%8C%E5%99%A8%20%2F%20%E9%97%AE%E7%94%A8%E6%88%B7%20%2F%20%E5%81%9C%E6%AD%A2%7C%20B%0A%20%20%20%20I%20--%3E%20L%5B%E5%8F%91%E5%B8%83%E4%BA%A7%E7%89%A9%20%C2%B7%20%E5%9B%9E%E5%A1%AB%E7%8A%B6%E6%80%81%E4%B8%8E%E7%9B%AE%E6%A0%87%E8%BF%9B%E5%BA%A6%5D%0A%20%20%20%20F%20--%3E%20M%5B%E7%BB%88%E6%80%81%E6%88%96%E5%8F%AF%E7%BB%A7%E7%BB%AD%5D%0A%20%20%20%20G%20--%3E%20M%0A%20%20%20%20H%20--%3E%20M%0A%20%20%20%20L%20--%3E%20M%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=d('<p>运行过程会持续产生进度事件，经过一层脱敏后才对外发布：单字段上限 8 千字符、总量 2 万 4 千字符，会覆盖私钥块、常见密钥前缀、云厂商访问键与 Bearer 令牌；超限后输出与文本字段会进一步压缩。</p><hr><h2 id="_6-检查点与续跑" tabindex="-1">6. 检查点与续跑 <a class="header-anchor" href="#_6-检查点与续跑" aria-label="Permalink to &quot;6. 检查点与续跑&quot;">​</a></h2><p>原生执行器会把检查点按序号写进工作区的隐藏目录，类型包括一轮对话结束、一次工具调用结束、上下文压缩、最终结论、预算耗尽、等待补充。恢复时不是简单读回来，而是先校验：任务目标哈希是否一致、权限摘要是否一致、外部副作用是否已结算。通过后<strong>使用量与轮次计数归零</strong>，防止续跑后预算被历史计数吃满。</p><p>停止服务时，仍在运行、等待补充、等待审批的任务一律被置为「可以继续」，等待下一次人工唤醒。</p><hr><h2 id="_7-失败、重试与预算" tabindex="-1">7. 失败、重试与预算 <a class="header-anchor" href="#_7-失败、重试与预算" aria-label="Permalink to &quot;7. 失败、重试与预算&quot;">​</a></h2><p>失败分类不依赖结构化错误码，而是<strong>对错误消息做正则匹配</strong>：限流、容量、连接失败、超时、权限、鉴权、transport、内部错误等共 11 类；其中「副作用结果不确定」优先级最高，会压过其它一切分类。</p><p>处置决策有 6 种：停止、问用户、修复、对账、换执行器接管、重试。</p><table tabindex="0"><thead><tr><th>项</th><th>规则</th></tr></thead><tbody><tr><td>最多尝试</td><td>3 次</td></tr><tr><td>重试间隔</td><td>指数退避，基数按失败类型取 1 秒或 5 秒，上限 5 分钟</td></tr><tr><td>允许「盲重试」的类型</td><td>只有超时、容量、限流、连接问题四类；其余必须走判定</td></tr><tr><td>默认运行预算</td><td>最多 200 轮、4000 次工具调用、10 小时时长</td></tr><tr><td>默认 token 上限</td><td>数值极大，实际是占位；真正卡住执行的是轮数与时长</td></tr></tbody></table><p>「20 亿 token」不是一个真实配额，读配置时不要把它当成预算约束。</p><hr><h2 id="_8-完成判定" tabindex="-1">8. 完成判定 <a class="header-anchor" href="#_8-完成判定" aria-label="Permalink to &quot;8. 完成判定&quot;">​</a></h2><p>判定结果有 4 种：通过、失败、受阻、需要人工。验收项状态分已通过/未通过/未执行/不适用，校验器有文件、结构、命令、Git、自定义五类。</p><p>命令校验器的边界很严：超时上限 2 分钟、参数个数上限、输出缓冲上限，环境变量只允许极少数系统变量；Git 校验器只接受「干净 / 指定分支 / 指定提交」三种声明，明确拒绝自由 shell。</p><p>判定失败的条件是命中了禁止动作、必需验收项未通过、或副作用判定为失败；有未结算的外部副作用则判为「受阻」。</p><hr><h2 id="_9-产物回收与状态文案" tabindex="-1">9. 产物回收与状态文案 <a class="header-anchor" href="#_9-产物回收与状态文案" aria-label="Permalink to &quot;9. 产物回收与状态文案&quot;">​</a></h2><p>产物发布有总量闸门：最多 1000 个文件、合计 100 MB；只有落在受管输出目录下的文件才会被识别为产物。任务状态文案覆盖 9 种状态，但执行器专属文案只写了原生与 Codex 两个，其余执行器在界面上一律显示为泛称「执行器」。</p><hr><h2 id="_10-只读代码才会发现的事实" tabindex="-1">10. 只读代码才会发现的事实 <a class="header-anchor" href="#_10-只读代码才会发现的事实" aria-label="Permalink to &quot;10. 只读代码才会发现的事实&quot;">​</a></h2><ol><li>「可以继续」被算作终态，必须靠外部动作唤醒，这是最容易踩的语义坑。</li><li>等待审批期间保留租约，是唯一不释放租约的收尾路径。</li><li>失败分类靠文本正则，且「副作用不确定」优先于所有类别。</li><li>并发配置缺键时按 1 跑，不是按默认 3 跑。</li><li>预算里的 token 上限是占位值，真实约束是轮数与时长。</li></ol><hr><h2 id="_11-与其它模块的分界" tabindex="-1">11. 与其它模块的分界 <a class="header-anchor" href="#_11-与其它模块的分界" aria-label="Permalink to &quot;11. 与其它模块的分界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>内容</th></tr></thead><tbody><tr><td>输入</td><td>任务与运行记录、应用设置、事件订阅、执行器注册表、租约服务、任务图、交接与委派服务、工作区、权限</td></tr><tr><td>输出</td><td>运行记录、执行结论、进度事件、任务状态与下一步动作、目标进度、产物记录</td></tr><tr><td>不讲</td><td>执行器内部怎么跑（模型适配）、提示词怎么编译（上下文）、审批票怎么生成（判定审批）、计划何时触发（定时任务）</td></tr></tbody></table><hr><h2 id="附-源码定位索引" tabindex="-1">附：源码定位索引 <a class="header-anchor" href="#附-源码定位索引" aria-label="Permalink to &quot;附：源码定位索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想看什么</th><th>去哪找</th></tr></thead><tbody><tr><td>主循环、并发、检查点、挂起恢复、产物回填</td><td><code>apps/server/src/scheduler.ts</code></td></tr><tr><td>失败分类、处置决策、重试延迟</td><td><code>apps/server/src/failure-policy.ts</code></td></tr><tr><td>完成判定与验收校验器</td><td><code>apps/server/src/completion-judge.ts</code></td></tr><tr><td>子任务图与并行约束</td><td><code>apps/server/src/task-graph.ts</code></td></tr><tr><td>租约与心跳</td><td><code>apps/server/src/leases.ts</code></td></tr><tr><td>进度脱敏</td><td><code>apps/server/src/progress-detail.ts</code></td></tr><tr><td>状态文案</td><td><code>apps/server/src/task-status-messages.ts</code></td></tr><tr><td>失败接管策略与上下文默认设置</td><td><code>apps/server/src/context-policy.ts</code>、<code>packages/core/src/types.ts</code></td></tr></tbody></table>',28))])}const C=E(i,[["render",n]]);export{D as __pageData,C as default};
